<?php use function KB\{e,url}; use KB\Security; ?>
<section class="page-heading"><div><span class="eyebrow">PEOPLE & PERMISSIONS</span><h1>Care for your community.</h1><p>Manage access, support members and keep administrator permissions intentional.</p></div><a class="button" href="<?= e(url('admin/users',['new'=>1])) ?>">Add account +</a></section>
<?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?>
<section class="panel" id="account-editor"><h2><?= $edit?'Edit account #'.(int)$edit['id']:'Add a new account' ?></h2><p class="muted">New members receive an email confirmation link. Ask them to change any temporary password after signing in.</p><form class="stack" method="post"><?= Security::csrfField() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><input type="hidden" name="action" value="save"><div class="form-grid"><label>Full name<input name="name" required minlength="2" maxlength="120" value="<?= e($edit['name']??'') ?>"></label><label>Email address<input name="email" type="email" required maxlength="190" value="<?= e($edit['email']??'') ?>"></label></div><div class="form-grid"><label>Role<select name="role"><option value="member">Member</option><option value="admin" <?= ($edit['role']??'')==='admin'?'selected':'' ?>>Administrator</option></select></label><label>Status<select name="status"><option value="active">Active</option><option value="suspended" <?= ($edit['status']??'')==='suspended'?'selected':'' ?>>Suspended</option></select></label></div><label><?= $edit?'New password (leave blank to keep unchanged)':'Temporary password' ?><input name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" <?= $edit?'':'required' ?>></label><div class="form-actions"><button class="button">Save account</button><a class="button secondary" href="<?= e(url('admin/users')) ?>">Clear form</a></div></form></section>
<section class="panel"><div class="section-heading"><h2>Accounts</h2><form class="search-form" method="get"><input type="hidden" name="route" value="admin/users"><input type="search" name="q" aria-label="Search accounts" value="<?= e($search) ?>" placeholder="Search names or emails…"><button class="button secondary small">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['name']) ?></strong><small><?= e($u['email']) ?></small></td><td><?= e(ucfirst($u['role'])) ?></td><td><span class="badge <?= $u['status']==='active'?'green':'red' ?>"><?= e(ucfirst($u['status'])) ?></span><small><?= $u['email_verified_at']?'Email confirmed':'Not verified' ?></small></td><td><div class="actions"><a href="<?= e(url('admin/users',['edit'=>$u['id']])) ?>">Edit</a><?php if((int)$u['id']!==KB\Auth::id()): ?><form method="post"><?= Security::csrfField() ?><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button name="action" value="<?= $u['status']==='active'?'suspend':'unsuspend' ?>" class="inline-button"><?= $u['status']==='active'?'Suspend':'Unsuspend' ?></button></form><?php if($u['role']==='member' && $u['status']==='active'): ?><form method="post" action="<?= e(url('admin/impersonate')) ?>" data-confirm="Open an audited support session for this member?"><?= Security::csrfField() ?><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="inline-button">Sign in as</button></form><?php endif; ?><form method="post"><?= Security::csrfField() ?><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button name="action" value="reset" class="inline-button">Reset password</button></form><form method="post" data-confirm="Permanently delete this account and its attempts? This cannot be undone."><?= Security::csrfField() ?><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button name="action" value="delete" class="danger-link">Delete</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__.'/../pagination.php'; ?></section>
